package verify

type Options struct {
	RefNameOverride string
	LatestOnly      bool
}

type Option func(o *Options)

func WithOverrideRefName(refNameOverride string) Option {
	return func(o *Options) {
		o.RefNameOverride = refNameOverride
	}
}

func WithLatestOnly() Option {
	return func(o *Options) {
		o.LatestOnly = true
	}
}

package verify

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestWithOverrideRefName(t *testing.T) {
	options := &Options{}

	option := WithOverrideRefName("refs/heads/main")

	option(options)

	assert.Equal(t, "refs/heads/main", options.RefNameOverride)
}

func TestWithLatestOnly(t *testing.T) {
	options := &Options{}

	option := WithLatestOnly()

	option(options)

	assert.True(t, options.LatestOnly)
}

