// WithInitialRootKeys anchors the read to a known first root of trust.
//
// Without it the first root in the RSL is trusted on sight, so anyone able to
// replace the RSL has the keys of their own history reported as fact.
func WithInitialRootKeys(pubs ...crypto.PublicKey) InspectOption {
	return func(o *inspectOptions) {
		o.initialRootKeys = pubs
	}
}

// WithEntry binds InspectRoot to one RSL policy entry instead of the latest
// one, for a caller verifying a specific published operation.
//
// entryID must name a reference entry for the policy ref that is reachable
// from the RSL. Both are load-bearing: GetEntry parses any commit whose
// message reads as an entry, and LoadState skips verification entirely when
// the RSL holds no applied policy, so an unreachable entry would otherwise be
// reported as root fact.
func WithEntry(entryID githash.Hash) InspectOption {
	return func(o *inspectOptions) {
		o.entryID = entryID
		o.atEntry = true
	}
}

// InspectRoot loads the applied policy and reports root facts. Loading verifies
// the metadata signatures and every root transition up to the loaded entry, so
// unsigned or tampered metadata fails.
//
// It does not establish that the history is the one you expect: the first root
// in the RSL is trusted on sight. Pass WithInitialRootKeys to anchor it.
//
// The policy comes from the RSL, not from the refs/gittuf/policy ref. Without
// options it reads the latest policy entry. See WithEntry.
func InspectRoot(ctx context.Context, store gitstore.Storer, opts ...InspectOption) (RootInfo, error) {
	options := &inspectOptions{}
	for _, fn := range opts {
		fn(options)
	}

	state, err := inspectState(ctx, store, options)
	if err != nil {
		return RootInfo{}, err
	}

	// LoadState skips verification when the RSL it reads holds no applied policy,
	// and it reads the RSL independently of inspectState's membership check. A
	// rewrite between the two reads would otherwise surface unsigned metadata.
	if err := state.Verify(ctx); err != nil {
		return RootInfo{}, fmt.Errorf("applied policy metadata does not verify: %w", err)
	}

	return rootInfoFromState(state)
}

func inspectState(ctx context.Context, store gitstore.Storer, options *inspectOptions) (*policy.State, error) {
	var loadOpts []policyopts.LoadStateOption
	if len(options.initialRootKeys) != 0 {
		principals, err := principalsFromPublicKeys(options.initialRootKeys)
		if err != nil {
			return nil, err
		}
		loadOpts = append(loadOpts, policyopts.WithInitialRootPrincipals(principals))
	}

	if !options.atEntry {
		return policy.LoadCurrentState(ctx, store, Ref, loadOpts...)
	}

	// Refused rather than treated as absent: falling back to the latest entry
	// would silently return a policy the caller did not ask for.
	if options.entryID.IsZero() {
		return nil, fmt.Errorf("WithEntry requires a non-zero RSL entry id")
	}

	// Membership first: GetEntry parses and caches any commit that reads as an
	// entry, including one no RSL ever recorded.
	rslTip, err := store.GetReference(rsl.Ref)
	if err != nil {
		return nil, err
	}

	reachable, err := store.KnowsCommit(rslTip, options.entryID)
	if err != nil {
		return nil, fmt.Errorf("unable to check RSL membership of %s: %w", options.entryID.String(), err)
	}
	if !reachable {
		return nil, fmt.Errorf("RSL entry %s is not reachable from %s", options.entryID.String(), rsl.Ref)
	}

)

