	if err != nil {
		return false, err
	}
	if _, err := s.commitObject(ancestor); err != nil {
		return false, err
	}

	found := false
	err = s.walk(commitID, func(h plumbing.Hash) bool {
		if h == ancestor {
			found = true
		}
		return !found
	})
