// History returns up to limit reference and propagation entries for ref,
// newest first, and how many such entries the RSL holds in total, counting
// beyond limit.
func (r *Reader) History(ctx context.Context, ref string, limit int) ([]Entry, int, error) {
	var (
		out   []Entry
		total int
	)
	err := r.walk(ctx, func(w raw) (bool, error) {
		if w.refName() != ref {
			return true, nil
		}
		total++
		if len(out) >= limit {
			return true, nil
		}
		e, err := r.build(w)
		if err != nil {
			return false, err
		}
		out = append(out, e)
		return true, nil
	})
	if err != nil {
		return nil, 0, err
	}
	return out, total, nil
}

