func TestIsCheckpointID(t *testing.T) {
	t.Parallel()

	for _, ok := range []string{"a3b2c4d5e6f7", "01JC0FFEE0BADC0DE00000007Z", "7ZZZZZZZZZZZZZZZZZZZZZZZZZ"} {
